// Pure ACC daily file build. No Firebase here: the bridge vendors this folder
// (scripts/sync-acc-core.js in ayala-bridge), so the cloud and the store
// laptop turn the same sales into byte-identical files.
const Moment = require('moment-timezone');
const Transaction = require('./models/Transaction');
const { AccDataBuilder } = require('./AccDataBuilder');
const { calcDailyFile } = require('./calcDailyFile');

const TZ = 'Asia/Manila';

/**
 * Z counts for a business day.
 * Dynamic (firstShiftKey set): current = days since activation + 1.
 * Legacy: current = stored zCounter + 1.
 *
 * @param {string} shiftKey  YYMMDD
 * @param {string|null} firstShiftKey  YYMMDD
 * @param {number} storedZCounter
 */
function zCountsFor(shiftKey, firstShiftKey, storedZCounter = 0) {
  const currentZCount = firstShiftKey
    ? Moment.tz(shiftKey, 'YYMMDD', TZ).diff(
        Moment.tz(firstShiftKey, 'YYMMDD', TZ),
        'days'
      ) + 1
    : storedZCounter + 1;
  return { previousZCount: currentZCount - 1, currentZCount };
}

/**
 * @param {Object} p
 * @param {string} p.shiftKey  YYMMDD
 * @param {{ key: string, val: object }[]} p.txns  raw RTDB transactions
 * @param {number[]} p.terminalNumbers
 * @param {Record<number, number>} p.oldGrandTotals  termNo -> PHP
 * @param {{ previousZCount: number, currentZCount: number }} p.zCounts
 * @param {string} p.posCode
 * @param {number} p.cc  upload counter for the day
 * @returns {{ filename: string, content: string, newTotals: Record<number, number> }}
 */
function buildDailyFile({
  shiftKey,
  txns,
  terminalNumbers,
  oldGrandTotals,
  zCounts,
  posCode,
  cc
}) {
  const day = Moment.tz(shiftKey, 'YYMMDD', TZ);
  const builder = new AccDataBuilder({
    sttUnx: day.clone().startOf('day').unix(),
    endUnx: day.clone().endOf('day').unix(),
    terminalNumbers,
    oldGrandTotals
  });

  // Key order fixes float summation order, so both sides round identically.
  const sorted = [...txns].sort((a, b) => Number(a.key) - Number(b.key));
  for (const { key, val } of sorted) {
    if (val) builder.process(new Transaction({ key, val }));
  }

  const data = builder.build(zCounts);
  const file = calcDailyFile(
    shiftKey,
    String(cc).padStart(2, '0'),
    { posCode },
    data
  );

  const newTotals = {};
  for (const t of data.terminals) {
    newTotals[t.terminalNumber] = t.dailySummary.newGrandTotal;
  }
  return { ...file, newTotals };
}

module.exports = { buildDailyFile, zCountsFor };
